style.css:
@-moz-document domain("roblox.com") {
/* =========================
     HEADER / UI COLORS
  ========================= */

  #header,
  #chat-header {
    background-color: #dce4ec !important;
  }

  .dialog-container .dialog-header {
    background-color: #dce4ec !important;
    color: #fff !important;
  }

  .navigation .notification-icon,
  .rbx-highlight {
    background: #dce4ec !important;
  }

  .slide-item-container-left,
  .profile-avatar-right {
    background: #d9ffcc !important;
  }

  .forum-table-header,
  body .forum-table-header th,
  body .forum-table-footer {
    background: #ccefff !important;
  }

  /* =========================
     BUTTONS
  ========================= */

  .rbx-upgrade-now #upgrade-now-button,
  .rbx-btn-secondary-xs.btn-more,
  #AjaxCommentsContainer button,
  .rbx-vip-server-create,
  .btn-secondary-xs {
    background-color: transparent !important;
    border-color: transparent !important;
  }

  /* =========================
     TEXT
  ========================= */

  body,
  .gotham-font .text {
    color: #000000 !important;
  }

  /* =========================
     BACKGROUND FIX (IMPORTANT)
  ========================= */

  html, body {
    background: none !important;
  }

  /* THE ONLY BACKGROUND LAYER (NO CONFLICTS) */
  html::before {
    content: "";
    position: fixed;
    inset: 0;
    background: url("https://files.catbox.moe/f435i9.jpg") center / cover no-repeat;
    z-index: -1;
    pointer-events: none;
  }

  /* =========================
     MAKE ROBLOX LAYERS TRANSPARENT
  ========================= */

  #root,
  .app-container,
  .site-content,
  .rbx-body,
  .content {
    background: transparent !important;
  }

  .content,
  .container-footer {
    background: transparent !important;
  }
}
